import subprocess, sys
from pathlib import Path

commands = [[sys.executable, 'benchmark_tests.py']]
commands.append([sys.executable, '-m', 'pytest', '-q', 'tests/test_strutils.py', 'tests/test_iterutils.py'])

if Path('agent_tests').exists():
    commands.append([sys.executable, '-m', 'pytest', '-q', 'agent_tests'])
for command in commands:
    code = subprocess.call(command)
    if code: sys.exit(code)
